Definition scU7_post (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32) (LB : list block) (LF : list fframe)
    (S ioc regb cfgb lo shi spa ff fp : Z) (xs2 xs3 xs7 errv : word) (p16 p24 : list byte) (cs1 : list cell) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a5 a6 a7 t3 t4 t5 t6 m' jt j219 j248 p16',
    ms' = MS (mkR (Z_to_bv 64 P_A_SC_CG5R) (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa)
                  (wz cfgb) (wz AL_STR_SCHEDULER) (wz (akey_lit KTask)) (wz 18446744073709551615) (wz 0) a5 a6 a7
                  xs2 xs3 (Z_to_bv 64 S) (Z_to_bv 64 (Z.shiftr (ioc + 8) 3 + 2147450880)) (Z_to_bv 64 (Z.shiftr (S + 224) 3 + 2147450880)) (Z_to_bv 64 (S + 232))
                  (Z_to_bv 64 (ioc + 8)) (Z_to_bv 64 (S + 224)) (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) t3 t4 t5 t6)
             F (Z_to_bv 64 P_A_CONFIG_GET_LONG) fc None m' (seg_rom bsegs)
